207	    /**
208	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
209	     * owner's {@code registrationDate} (falling back to the current date when no registration date
210	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
211	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
212	     */
213	    @Transient
214	    public String getAgeBand() {
215	        if (this.birthDate == null) {
216	            return null;
217	        }
218	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
219	        int age = Period.between(this.birthDate, reference).getYears();
220	        if (age < 18) {
221	            return "MINOR";
222	        }
223	        if (age < 65) {
224	            return "ADULT";
225	        }
226	        return "SENIOR";
