237	    /**
238	     * The leading alphabetic REGION segment of a {@code memberId} formatted
239	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code 'NSW'} for {@code 'NSW271A2B3C4D5'}), or
240	     * {@code null} when {@code memberId} is {@code null} or does not begin with a letter. REGION is
241	     * always a run of letters immediately followed by the 2-digit fiscal year, so the leading letter
242	     * run is exactly the region code.
243	     */
244	    public static String regionSegment(String memberId) {
245	        if (memberId == null) {
246	            return null;
247	        }
248	        int i = 0;
249	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
250	            i++;
251	        }
252	        return i == 0 ? null : memberId.substring(0, i);
253	    }
254	
255	    /**
256	     * The 2-digit fiscal-year (FY) segment of a {@code memberId} formatted
257	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code '27'} for {@code 'NSW271A2B3C4D5'}), the two
258	     * digits immediately following the {@link #regionSegment(String) REGION}. Returns {@code null}
259	     * when {@code memberId} has no region prefix or is too short to carry a 2-digit FY.
260	     */
261	    public static String fiscalYearSegment(String memberId) {
262	        String region = regionSegment(memberId);
263	        if (region == null || memberId.length() < region.length() + 2) {
264	            return null;
265	        }
266	        String fy = memberId.substring(region.length(), region.length() + 2);
267	        for (int i = 0; i < fy.length(); i++) {
268	            if (fy.charAt(i) < '0' || fy.charAt(i) > '9') {
269	                return null;
270	            }
271	        }
272	        return fy;
273	    }
