291	    /**
292	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
293	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
294	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
295	     * the owner's tenure is at least one elapsed fiscal year (measured from the
296	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
297	     */
298	    @Transient
299	    public Integer getMembershipPoints() {
300	        int points = 0;
301	        if (this.email != null && !this.email.isBlank()) {
302	            points += 2;
303	        }
304	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
305	            points += 1;
306	        }
307	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
308	            points += 2;
309	        }
310	        if (hasTenureOverOneFiscalYear()) {
311	            points += 3;
312	        }
313	        return points;
314	    }
315	
316	    /**
317	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
318	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
319	     * points, and level 4 for 6 or more points. The result is then capped at the owner's
320	     * {@code membershipLevelCap} when one has been assigned, so a new household member can never
321	     * exceed one above the highest level already present in their household (see
322	     * {@link #getMembershipLevelCap()}).
323	     */
324	    @Transient
325	    public Integer getMembershipLevel() {
326	        int points = getMembershipPoints();
327	        int level;
328	        if (points <= 1) {
329	            level = 1;
330	        }
331	        else if (points <= 3) {
332	            level = 2;
333	        }
334	        else if (points <= 5) {
335	            level = 3;
336	        }
337	        else {
338	            level = 4;
339	        }
340	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
341	            return this.membershipLevelCap;
342	        }
343	        return level;
344	    }
345	
346	    /**
347	     * The ceiling applied to this owner's derived {@code membershipLevel}: one above the highest
348	     * {@code membershipLevel} among the owner's household members (same last name and postcode) at
349	     * creation time. {@code null} when the owner had no existing household member, in which case no
350	     * cap applies.
351	     */
352	    public Integer getMembershipLevelCap() {
353	        return this.membershipLevelCap;
354	    }
355	
356	    public void setMembershipLevelCap(Integer membershipLevelCap) {
357	        this.membershipLevelCap = membershipLevelCap;
358	    }
359	
360	    /**
361	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
362	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
363	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
364	     * never qualifies.
365	     */
366	    @Transient
367	    private boolean hasTenureOverOneFiscalYear() {
368	        if (this.registrationDate == null) {
369	            return false;
370	        }
371	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
372	    }
373	
374	    /**
375	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the two-digit
376	     * fiscal-year (FY) segment carried by the owner's {@code memberId}
377	     * ({@code '<REGION><FY><HASH8><CHK>'}), so the reported fiscal year and the FY embedded in the
378	     * memberId stay in lock-step. Falls back to computing YY from the last two digits of the fiscal
379	     * year of the owner's business-day-adjusted {@code registrationDate} (the fiscal year starting on
380	     * 1 July, so a registration on or after 1 July belongs to the fiscal year ending the following
381	     * 30 June) when the owner has no {@code memberId} yet. Returns {@code null} when the owner has
382	     * neither a {@code memberId} nor a {@code registrationDate}, so the field is omitted from the
383	     * response.
384	     */
385	    @Transient
386	    public String getFiscalYear() {
387	        String fy = fiscalYearSegment(this.memberId);
388	        if (fy != null) {
389	            return "FY" + fy;
390	        }
391	        if (this.registrationDate == null) {
392	            return null;
393	        }
394	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
395	    }
396	
397	    /**
398	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
399	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
400	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
401	     * current year's fiscal year.
402	     */
403	    public static int fiscalYearOf(LocalDate date) {
404	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
405	    }
406	
407	    /**
408	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners: the
409	     * full lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
410	     * soundex(lastName)}. The telephone and email are already stored in their canonical (E.164 /
411	     * lower-cased) form, so a {@code null} or blank email contributes an empty middle segment, and
412	     * the last name is reduced to its {@link Soundex} code (empty when there is no last name). Two
413	     * owners are duplicates only when their whole {@code identityKey} is equal.
414	     */
415	    @Transient
416	    public String getIdentityKey() {
417	        String telephonePart = this.telephone == null ? "" : this.telephone;
418	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
419	        String soundexPart = Soundex.encode(getLastName());
420	        return Sha256.hex(telephonePart + "|" + emailPart + "|" + soundexPart);
421	    }
422	
423	    public boolean isBulkSignupWarning() {
424	        return this.bulkSignupWarning;
425	    }
426	
427	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
428	        this.bulkSignupWarning = bulkSignupWarning;
429	    }
