441	        this.capacityWarning = capacityWarning;
442	    }
443	
444	    public Integer getHouseholdMemberCount() {
445	        return this.householdMemberCount;
446	    }
447	
448	    public void setHouseholdMemberCount(Integer householdMemberCount) {
449	        this.householdMemberCount = householdMemberCount;
450	    }
451	
452	    /**
453	     * Whether this owner was flagged at creation as a possible (soft) duplicate: its
454	     * {@code identityKey} differs from every existing owner's, but it shares an existing owner's
455	     * {@code soundex(lastName)} and postcode. The owner is still created; this flag is advisory.
456	     */
457	    public boolean isPossibleDuplicate() {
458	        return this.possibleDuplicate;
459	    }
460	
461	    public void setPossibleDuplicate(boolean possibleDuplicate) {
462	        this.possibleDuplicate = possibleDuplicate;
463	    }
464	
465	    /**
466	     * The id of the existing owner this one soft-matched against (same {@code soundex(lastName)} and
467	     * postcode, different {@code identityKey}), or {@code null} when {@link #isPossibleDuplicate()}
468	     * is {@code false}.
469	     */
470	    public Integer getPossibleDuplicateOf() {
471	        return this.possibleDuplicateOf;
472	    }
473	
474	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
475	        this.possibleDuplicateOf = possibleDuplicateOf;
476	    }
477	
478	    /**
479	     * Whether this owner has been soft-deleted: DELETE /api/owners/{id} sets this flag rather than
480	     * removing the row, so the owner is retained and still readable but is ignored by the create
481	     * endpoint's duplicate and identity checks. A newly created owner is not deleted.
482	     */
483	    public boolean isDeleted() {
484	        return this.deleted;
485	    }
486	
487	    public void setDeleted(boolean deleted) {
488	        this.deleted = deleted;
489	    }
490	
491	    /**
492	     * The {@code Idempotency-Key} the owner was first created under, or {@code null} when the create
493	     * carried no such header. When a create repeats with an already-seen key, the originally created
494	     * owner is returned instead of a duplicate being created, so the key is retained to recognise the
495	     * repeat.
496	     */
497	    public String getIdempotencyKey() {
498	        return this.idempotencyKey;
499	    }
500	
501	    public void setIdempotencyKey(String idempotencyKey) {
502	        this.idempotencyKey = idempotencyKey;
503	    }
504	
505	    protected Set<Pet> getPetsInternal() {
506	        if (this.pets == null) {
507	            this.pets = new HashSet<>();
508	        }
509	        return this.pets;
510	    }
511	
512	    protected void setPetsInternal(Set<Pet> pets) {
513	        this.pets = pets;
514	    }
515	
516	    public List<Pet> getPets() {
517	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
518	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
519	        return Collections.unmodifiableList(sortedPets);
520	    }
521	
522	    public void setPets(List<Pet> pets) {
523	        this.pets = new HashSet<>(pets);
524	    }
525	
526	    public void addPet(Pet pet) {
527	        getPetsInternal().add(pet);
528	        pet.setOwner(this);
529	    }
530	
531	    /**
532	     * Return the Pet with the given name, or null if none found for this Owner.
533	     *
534	     * @param name to test
535	     * @return true if pet name is already in use
536	     */
537	    public Pet getPet(String name) {
538	        return getPet(name, false);
539	    }
540	
541	    /**
542	     * Return the Pet with the given name, or null if none found for this Owner.
543	     *
544	     * @param name to test
545	     * @return true if pet name is already in use
546	     */
547	    public Pet getPet(String name, boolean ignoreNew) {
548	        name = name.toLowerCase();
549	        for (Pet pet : getPetsInternal()) {
550	            if (!ignoreNew || !pet.isNew()) {
551	                String compName = pet.getName();
552	                compName = compName.toLowerCase();
553	                if (compName.equals(name)) {
554	                    return pet;
555	                }
556	            }
557	        }
558	        return null;
559	    }
560	
561	    public Pet getPet(Integer petId) {
562	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
563	    }
564	
565	    @Override
566	    public String toString() {
567	        return new ToStringCreator(this)
568	
569	            .append("id", this.getId())
570	            .append("new", this.isNew())
571	            .append("lastName", this.getLastName())
572	            .append("firstName", this.getFirstName())
573	            .append("address", this.address)
574	            .append("city", this.city)
575	            .append("telephone", this.telephone)
576	            .toString();
577	    }
578	}
