274	    @Override
275	    @Transactional
276	    public void saveOwner(Owner owner) throws DataAccessException {
277	        boolean isNew = owner.isNew();
278	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
279	        // roll it forward to the next business day so it never lands on a weekend. Everything
280	        // derived from the registration date below must use this adjusted value.
281	        LocalDate registrationDate = toBusinessDay(
282	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
283	        owner.setRegistrationDate(registrationDate);
284	        if (owner.isNew()) {
285	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
286	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
287	            // it automatically. It no longer feeds the identityKey, but is still reported and drives
288	            // the household member count and level cap below.
289	            owner.setHouseholdId(computeHouseholdId(owner));
290	            // The household is keyed on (last name, postcode), so the members are the existing owners
291	            // sharing both with this owner.
292	            List<Owner> householdMembers = findHouseholdMembers(owner);
293	            // Size of the household after this create: the existing members plus this new owner.
294	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
295	            // A new owner joining an existing household has its derived membershipLevel capped at one
296	            // above the current maximum membershipLevel among its household members, so a new member
297	            // can never leap more than one level past the household. With no existing member no cap
298	            // applies.
299	            if (!householdMembers.isEmpty()) {
300	                int maxLevel = householdMembers.stream()
301	                    .mapToInt(Owner::getMembershipLevel)
302	                    .max()
303	                    .getAsInt();
304	                owner.setMembershipLevelCap(maxLevel + 1);
305	            }
306	        }
307	        // Single duplicate check: reject only when the new owner's WHOLE identityKey (the SHA-256 of
308	        // normalizedTelephone | email-or-empty | soundex(lastName)) equals an existing owner's. This
309	        // is the only 409; there is no separate household-duplicate rejection.
310	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
311	            throw new DuplicateIdentityException(owner.getIdentityKey());
312	        }
313	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's
314	        // soundex(lastName) and postcode. Still created, but flagged as a possible duplicate pointing
315	        // at the matching owner. Because the telephone is part of the identityKey, two owners with the
316	        // same last name and postcode but different telephones are flagged here rather than rejected.
317	        if (owner.isNew()) {
318	            Owner softMatch = findPossibleDuplicate(owner);
319	            if (softMatch != null) {
320	                owner.setPossibleDuplicate(true);
321	                owner.setPossibleDuplicateOf(softMatch.getId());
322	            }
323	        }
324	        if (owner.isNew()) {
325	            long ownersInCity = countOwnersInCity(owner);
326	            if (ownersInCity >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
327	                throw new CityOwnerLimitExceededException(owner.getCity());
328	            }
329	            // Between 40 and 49 existing owners (inclusive): created, but flagged as approaching the
330	            // per-city capacity limit of 50.
331	            owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
332	        }
333	        if (owner.isNew()
334	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
335	            throw new DailyOwnerLimitExceededException(registrationDate);
336	        }
337	        if (owner.isNew() && owner.getMemberId() == null) {
338	            owner.setMemberId(generateMemberId(owner));
339	        }
340	        if (owner.isNew()) {
341	            owner.setNamesakeCount(countNamesakes(owner));
342	            owner.setBulkSignupWarning(
343	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
344	        }
345	        ownerRepository.save(owner);
346	        if (isNew) {
347	            AUDIT.info("owner created id={} memberId={} membershipLevel={} registrationDate={}",
348	                owner.getId(), owner.getMemberId(), owner.getMembershipLevel(),
349	                owner.getRegistrationDate());
350	            AUDIT.info(ownerCreatedEvent(owner));
351	            // Enqueue a welcome notification carrying the owner id and the memberId.
352	            NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
353	        }
354	    }
355	
356	    /**
357	     * Build the immutable structured owner-created event emitted alongside the human-readable audit
358	     * line and serialize it to JSON. {@code seq} is a process-wide monotonically increasing integer
359	     * stamped once per create, so the ordering of creates is recoverable from the audit stream.
360	     *
361	     * <p>The event carries the owner's <em>primary identifier</em> under the {@code memberId} field
362	     * (see {@link #primaryIdentifier(Owner)}), the unified member id that replaced the former
363	     * customerCode and membershipNumber.
364	     */
365	    private String ownerCreatedEvent(Owner owner) {
366	        OwnerCreatedEvent event = new OwnerCreatedEvent(
367	            OWNER_CREATED_SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner),
368	            owner.getMembershipLevel(), "OWNER_CREATED");
369	        return AUDIT_MAPPER.writeValueAsString(event);
370	    }
371	
372	    /**
373	     * The owner's primary identifier carried by audit events: the unified {@code memberId}. The
374	     * single source of truth lives here so every emitted event references the same identifier.
375	     */
376	    private String primaryIdentifier(Owner owner) {
377	        return owner.getMemberId();
378	    }
379	
380	    /**
381	     * Immutable structured owner-created audit event. Serialized to the JSON object
382	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}; the
383	     * {@code memberId} field carries the owner's primary identifier.
384	     */
385	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
386	        Integer membershipLevel, String event) {
387	    }
388	
389	    /**
390	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
391	     * (non-deleted) owner. The key is the SHA-256 of telephone, email and {@code soundex(lastName)}
392	     * combined, so two owners collide only when their whole key is equal (see
393	     * {@link Owner#getIdentityKey()}).
394	     */
395	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
396	        String identityKey = owner.getIdentityKey();
397	        return ownerRepository.findAll().stream()
398	            .filter(existing -> !existing.isDeleted())
399	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
400	    }
401	
402	    /**
403	     * Find an existing owner this (new) owner soft-matches against: one sharing the same
404	     * {@code soundex(lastName)} and postcode, but carrying a different {@code identityKey}. Returns
405	     * the lowest-id such owner, or {@code null} when the owner has no last name or postcode to match
406	     * on, or nothing matches. The caller only invokes this once the hard {@code identityKey}
407	     * duplicate check has already passed.
408	     */
409	    private Owner findPossibleDuplicate(Owner owner) {
410	        String key = soundexPostcodeKey(owner);
411	        if (key == null) {
412	            return null;
413	        }
414	        String identityKey = owner.getIdentityKey();
415	        return ownerRepository.findAll().stream()
416	            .filter(existing -> !existing.isDeleted())
417	            .filter(existing -> key.equals(soundexPostcodeKey(existing))
418	                && !identityKey.equals(existing.getIdentityKey()))
419	            .min(Comparator.comparing(Owner::getId))
420	            .orElse(null);
421	    }
422	
423	    /**
424	     * Build the soft-match key, {@code soundex(lastName) + '|' + postcode}: the basis on which a new
425	     * owner is flagged a possible duplicate of an existing owner. Returns {@code null} when the owner
426	     * has no last name to encode or no postcode to key on.
427	     */
428	    private String soundexPostcodeKey(Owner owner) {
429	        String soundex = Soundex.encode(owner.getLastName());
430	        String postcode = owner.getPostcode();
431	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
432	            return null;
433	        }
434	        return soundex + "|" + postcode;
435	    }
436	
437	    /**
438	     * Count the owners that already exist (before this create) sharing the same first name and last
439	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
440	     * unique among the existing owners.
441	     */
442	    private int countNamesakes(Owner owner) {
443	        String firstName = owner.getFirstName();
444	        String lastName = owner.getLastName();
445	        if (firstName == null || lastName == null) {
446	            return 0;
447	        }
448	        return (int) ownerRepository.findAll().stream()
449	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
450	                && lastName.equalsIgnoreCase(existing.getLastName()))
451	            .count();
452	    }
453	
454	    /**
455	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
456	     * last name and its postcode. Last names are compared case-insensitively with collapsed
457	     * whitespace; postcodes are compared exactly. This is the same keying used by
458	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
459	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
460	     * postcode to match on.
461	     */
462	    private List<Owner> findHouseholdMembers(Owner owner) {
463	        String key = householdKey(owner);
464	        if (key == null) {
465	            return List.of();
466	        }
467	        return ownerRepository.findAll().stream()
468	            .filter(existing -> !existing.isDeleted())
469	            .filter(existing -> key.equals(householdKey(existing)))
470	            .toList();
471	    }
472	
473	    /**
474	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
475	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
476	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
477	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
478	     * postcode, so it does not belong to a shared household.
479	     */
480	    private String computeHouseholdId(Owner owner) {
481	        String key = householdKey(owner);
482	        return key == null ? null : Sha256.hexPrefix(key, 6, false);
483	    }
484	
485	    /**
486	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
487	     * that identifies a household. The last name is normalized case-insensitively with collapsed
488	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
489	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
490	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
491	     * cannot drift apart.
492	     */
493	    private String householdKey(Owner owner) {
494	        String lastName = normalizeHouseholdKey(owner.getLastName());
495	        String postcode = owner.getPostcode();
496	        if (lastName == null || postcode == null || postcode.isBlank()) {
497	            return null;
498	        }
499	        return lastName + "|" + postcode;
500	    }
501	
502	    /**
503	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
504	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
505	     */
506	    private String normalizeHouseholdKey(String value) {
507	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
508	    }
509	
510	    /**
511	     * Build an owner's unified {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}: REGION the
512	     * region code resolved from the owner's postcode (falling back to the owner's city, else
513	     * {@code 'UNKNOWN'}); FY the two-digit fiscal year of the owner's business-day-adjusted
514	     * {@code registrationDate} (the fiscal year starting 1 July); HASH8 the first 8 upper-case hex
515	     * characters of SHA-256 computed over the owner's normalized telephone concatenated with the
516	     * owner's last name; and CHK a single Luhn check digit computed over the digits of
517	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW271A2B3C4D5'}). The identity is fully derived
518	     * from the owner's own attributes.
519	     * <p>
520	     * When the derived id collides with an existing owner's {@code memberId}, a {@code '-<n>'}
521	     * suffix is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct
522	     * owners always receive distinct member ids.
523	     */
524	    private String generateMemberId(Owner owner) {
525	        String region = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity());
526	        String fy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
527	        String core = region + fy + memberHash(owner);
528	        return deduplicateMemberId(core + luhnCheckDigit(core));
529	    }
530	
531	    /**
532	     * Return {@code base} when no existing owner already uses it as their {@code memberId};
533	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
534	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
535	     */
536	    private String deduplicateMemberId(String base) {
537	        Set<String> existing = ownerRepository.findAll().stream()
538	            .map(Owner::getMemberId)
539	            .filter(Objects::nonNull)
540	            .collect(Collectors.toSet());
541	        if (!existing.contains(base)) {
542	            return base;
543	        }
544	        int n = 2;
545	        while (existing.contains(base + "-" + n)) {
546	            n++;
547	        }
548	        return base + "-" + n;
549	    }
550	
551	    /**
552	     * Compute the HASH8 segment of an owner's {@code memberId}: the first 8 upper-case hex
553	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
554	     * with the owner's last name.
555	     */
556	    private String memberHash(Owner owner) {
557	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
558	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
559	        return Sha256.hexPrefix(telephone + lastName, 4, true);
560	    }
561	
562	    /**
563	     * Compute the single Luhn check digit (0-9) over the digits contained in {@code s}; non-digit
564	     * characters are ignored. This is the CHK segment appended to {@code <REGION><FY><HASH8>} to
565	     * form the owner's {@code memberId}.
566	     */
567	    private int luhnCheckDigit(String s) {
568	        int sum = 0;
569	        boolean dbl = true;
570	        for (int i = s.length() - 1; i >= 0; i--) {
571	            char c = s.charAt(i);
572	            if (c < '0' || c > '9') {
573	                continue;
574	            }
575	            int d = c - '0';
576	            if (dbl) {
577	                d *= 2;
578	                if (d > 9) {
579	                    d -= 9;
580	                }
581	            }
582	            sum += d;
583	            dbl = !dbl;
584	        }
585	        return (10 - (sum % 10)) % 10;
586	    }
587	
588	    /**
589	     * Count the owners that already exist (before this create) in the same city as {@code owner},
590	     * compared case-insensitively.
591	     */
592	    private long countOwnersInCity(Owner owner) {
593	        String city = owner.getCity();
594	        return ownerRepository.findAll().stream()
595	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
596	            .count();
597	    }
598	
599	    /**
600	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
601	     * on the given {@code date}. Used to enforce the per-day create cap.
602	     */
603	    private long countOwnersRegisteredOn(LocalDate date) {
604	        return ownerRepository.findAll().stream()
605	            .filter(existing -> date.equals(existing.getRegistrationDate()))
606	            .count();
607	    }
608	
609	    /**
610	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
611	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
612	     */
613	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
614	        LocalDate.parse("2026-01-01"),
615	        LocalDate.parse("2026-01-26"),
616	        LocalDate.parse("2026-04-25"),
617	        LocalDate.parse("2026-12-25"),
618	        LocalDate.parse("2026-12-28"));
619	
620	    /**
621	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
622	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
623	     * unchanged. Registration dates are required to fall on a business day.
624	     */
625	    private LocalDate toBusinessDay(LocalDate date) {
626	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
627	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
628	            || PUBLIC_HOLIDAYS.contains(date)) {
629	            date = date.plusDays(1);
630	        }
631	        return date;
632	    }
633	
634	    @Override
635	    @Transactional(readOnly = true)
636	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
637	        return ownerRepository.findByLastName(lastName);
638	    }
639	
640	    /**
641	     * Find the owner originally created under the given {@code Idempotency-Key}, or {@code null} when
642	     * the key is blank or no (non-deleted) owner carries it. Used by the create endpoint to recognise
643	     * a repeated create and return the first-created owner instead of creating a duplicate.
644	     */
645	    @Override
646	    @Transactional(readOnly = true)
647	    public Owner findOwnerByIdempotencyKey(String idempotencyKey) throws DataAccessException {
648	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
649	            return null;
650	        }
651	        return ownerRepository.findByIdempotencyKey(idempotencyKey);
652	    }
653	
654	    @Override
655	    @Transactional(readOnly = true)
656	    public Collection<Visit> findVisitsByPetId(int petId) {
657	        return visitRepository.findByPetId(petId);
658	    }
659	
660	    @Override
661	    @Transactional(readOnly = true)
662	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
663	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
664	    }
665	
666	    private <T> T findEntityById(Supplier<T> supplier) {
667	        try {
668	            return supplier.get();
669	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
670	            // Just ignore not found exceptions for Jdbc/Jpa realization
671	            return null;
672	        }
673	    }
674	
675	}
